    SELECT
        'ABNO'||
        LPAD(NVL(TO_NUMBER(SUBSTR(MAX(BOARD_NO), LENGTH('ABNO' ) + 1)), 0) + 1, 6, '0')
    FROM ADMIN_BOARD


INSERT INTO ADMIN_BOARD (
	  BOARD_NO
	, USER_ID
	, BOARD_TYPE_CODE
	, BOARD_TITLE
	, BOARD_WRITE_DATE
	, BOARD_CONTENT
	, BOARD_POST_HIT
	, BOARD_STATUS
) VALUES (
	  #{boardNo}
	, #{userId}



				, #{cmnCodeGroupVOList[0].cmnCodeList[0].codeDetailNo}


				, #{boardTypeCode}



	, #{boardTitle}
	, sysdate
	, #{boardContent}
	, 0
	, 'R'
)

mapper.update:
UPDATE ADMIN_BOARD 
SET 
	  USER_ID = #{userId}
	, BOARD_TYPE_CODE = #{boardTypeCode}
	, BOARD_TITLE = #{boardTitle}
	, BOARD_CONTENT = #{boardContent}
	, BOARD_DELETE_DATE = #{boardDeleteDate}
	, BOARD_POST_HIT = #{boardPostHit}
	, BOARD_STATUS = 'U'
WHERE 
	BOARD_NO = #{boardNo}
